// WF-03 Node 2: Phân tích và bóc tách Stack Trace lỗi từ Backend
try {
  const input = $input.first().json;
  const raw = input.body?.data || input.body || input.data || input;

  const statusCode = parseInt(raw.statusCode || 500, 10);
  const endpoint = String(raw.path || raw.endpoint || raw.url || '/api/unknown').trim();
  const method = String(raw.method || 'POST').toUpperCase();
  const errorMessage = String(raw.message || raw.error || 'Internal Server Error').substring(0, 300);
  const stackTrace = String(raw.stack || raw.stackTrace || '').substring(0, 1500);
  const userId = raw.userId || 'GUEST';
  const timestamp = raw.timestamp || new Date().toISOString();

  const fileMatch = stackTrace.match(/at\s+(?:.*?)\s+\((.*?):(\d+):(\d+)\)/i) || stackTrace.match(/at\s+(.*?):(\d+):(\d+)/i);
  const culpritFile = fileMatch ? fileMatch[1].split(/[\\/]/).pop() : 'UnknownModule.ts';
  const culpritLine = fileMatch ? fileMatch[2] : 'N/A';

  return [{
    json: {
      statusCode,
      endpoint,
      method,
      errorMessage,
      culpritFile,
      culpritLine,
      stackTrace: stackTrace || errorMessage,
      userId,
      timestamp,
      isDatabaseError: errorMessage.includes('ER_') || errorMessage.includes('QueryFailedError') || errorMessage.includes('Connection lost')
    }
  }];
} catch (err) {
  throw new Error('[WF-03 Parse Error] Failed: ' + err.message);
}

// WF-03 Node 3: Chống bão cảnh báo
const item = $input.first().json;
const errorSignature = `${item.method}_${item.endpoint}_${item.culpritFile}_${item.culpritLine}`.replace(/[^a-zA-Z0-9_]/g, '');
const incidentRef = 'ERR-' + Date.now().toString(36).toUpperCase();
const shouldNotifyImmediately = item.statusCode >= 500;

return [{
  json: {
    ...item,
    errorSignature,
    incidentRef,
    shouldNotifyImmediately
  }
}];

// WF-03 Node 5: Gemini AI Root Cause Analysis
const item = $input.first().json;
let rootCause = 'Lỗi logic hoặc dữ liệu đầu vào không hợp lệ.';
let suggestedFix = 'Kiểm tra lại ValidationPipe hoặc kiểu dữ liệu trong DTO.';

if (item.isDatabaseError) {
  rootCause = 'Xung đột khóa ngoại, trùng lặp Unique Index hoặc mất kết nối tới pool MySQL.';
  suggestedFix = 'Sử dụng pessimistic lock, bọc giao dịch trong Transaction runner hoặc bổ sung câu lệnh try/catch bắt ER_DUP_ENTRY.';
} else if (item.errorMessage.includes('Cannot read properties of undefined') || item.errorMessage.includes('is not defined')) {
  rootCause = 'Truy cập thuộc tính của đối tượng null/undefined hoặc thiếu import component/thư viện.';
  suggestedFix = 'Sử dụng Optional Chaining (?.) hoặc kiểm tra kỹ danh sách import ở đầu file ' + item.culpritFile;
}

return [{
  json: {
    ...item,
    aiDiagnostic: {
      rootCause,
      suggestedFix,
      severity: item.isDatabaseError ? 'DATABASE_CRITICAL' : 'LOGIC_HIGH'
    }
  }
}];

// WF-03 Node 6: Định dạng Playbook khắc phục sự cố
const item = $input.first().json;
const formattedPlaybook = `
🔥 [SỰ CỐ HỆ THỐNG CẦN XỬ LÝ]: ${item.incidentRef}
• API Endpoint: ${item.method} ${item.endpoint}
• Vị trí nghi vấn: File ${item.culpritFile} (Dòng ${item.culpritLine})
• Thông báo lỗi: ${item.errorMessage}
• Chẩn đoán AI: ${item.aiDiagnostic.rootCause}
• Hướng dẫn khắc phục: ${item.aiDiagnostic.suggestedFix}
`;

return [{
  json: {
    ...item,
    formattedPlaybook
  }
}];
